// Measures hard loads, client navigations and the Overview -> Cash flow -> Out -> Uncategorized workflow.
// Usage: node .qa/perf/bench.mjs <label> [runs]
import { chromium } from "@playwright/test";
import fs from "node:fs";
const label = process.argv[2] ?? "run", RUNS = Number(process.argv[3] ?? 5);
const BASE = process.env.BASE ?? "http://localhost:3000";
const FETCH_LOG = ".qa/perf/fetch.log";
const routes = ["/", "/money/transactions", "/money/organization", "/money/investigations", "/import", "/money/accounts", "/money/recurring", "/plan", "/plan/spending", "/plan/currency", "/money/wealth", "/ai", "/ai/agents", "/ai/activity", "/ai/artifacts", "/settings", "/notifications"];
const browser = await chromium.launch();
const context = await browser.newContext({ storageState: "e2e/.auth.json", viewport: { width: 1440, height: 900 } });
const page = await context.newPage();
const consoleErrors = [];
page.on("console", msg => { if (msg.type() === "error") consoleErrors.push(`${page.url()} ${msg.text().slice(0, 200)}`); });
page.on("pageerror", err => consoleErrors.push(`${page.url()} pageerror ${err.message.slice(0, 200)}`));
let rscRequests = 0; page.on("request", r => { if (r.headers()["rsc"] === "1" || r.url().includes("_rsc=")) rscRequests++; });

const fetchCount = () => fs.existsSync(FETCH_LOG) ? fs.readFileSync(FETCH_LOG, "utf8").split("\n").filter(Boolean).length : 0;

// In-page: run `act` (a click) and time first DOM response + data-ready.
async function timed(actSelector, readyFn, readyArg) {
  return page.evaluate(async ({ actSelector, readyFn, readyArg }) => {
    const ready = new Function("arg", readyFn);
    const oldMain = document.querySelector("main");
    const el = typeof actSelector === "string" ? document.querySelector(actSelector) : null;
    if (!el) throw new Error(`missing ${actSelector}`);
    let first = null;
    const t0 = performance.now();
    const mo = new MutationObserver(() => { if (first === null) first = performance.now() - t0; });
    mo.observe(document.getElementById("main-content") ?? document.body, { childList: true, subtree: true, characterData: true, attributes: true });
    el.click();
    return await new Promise((resolve, reject) => {
      const deadline = t0 + 30000;
      const tick = () => {
        if (ready(arg = { ...readyArg, oldMain })) { mo.disconnect(); resolve({ firstMs: first ?? performance.now() - t0, readyMs: performance.now() - t0 }); return; }
        if (performance.now() > deadline) { mo.disconnect(); reject(new Error(`timeout ${actSelector} ${location.href}`)); return; }
        requestAnimationFrame(tick);
      };
      var arg; tick();
    });
  }, { actSelector, readyFn, readyArg });
}
// Ready: on target path, a new non-busy <main> with an h1, nothing aria-busy inside it.
const pageReady = `const m = document.querySelector("main"); return location.pathname === arg.path && (!arg.search || location.search.includes(arg.search)) && m && m !== arg.oldMain && !m.matches('[aria-busy="true"]') && m.querySelector("h1") && !m.querySelector('[aria-busy="true"]');`;

async function hardLoad(path) {
  await page.goto(BASE + "/about:blank".slice(0, 0) + "data:,", { waitUntil: "commit" }).catch(() => {});
  const t = Date.now();
  await page.goto(BASE + path, { waitUntil: "commit" });
  await page.waitForFunction(() => { const m = document.querySelector("main"); return m && !m.matches('[aria-busy="true"]') && m.querySelector("h1") && !m.querySelector('[aria-busy="true"]') && document.readyState === "complete"; }, null, { timeout: 60000, polling: "raf" });
  const ready = Date.now() - t;
  const nav = await page.evaluate(() => new Promise(resolve => {
    const n = performance.getEntriesByType("navigation")[0];
    let lcp = null; new PerformanceObserver(list => { const e = list.getEntries().at(-1); if (e) lcp = e.startTime; }).observe({ type: "largest-contentful-paint", buffered: true });
    const fcp = performance.getEntriesByName("first-contentful-paint")[0]?.startTime ?? null;
    setTimeout(() => resolve({ ttfb: n.responseStart, fcp, lcp, dcl: n.domContentLoadedEventEnd, load: n.loadEventEnd, transfer: n.transferSize }), 50);
  }));
  const js = await page.evaluate(() => performance.getEntriesByType("resource").filter(r => r.initiatorType === "script" || r.name.endsWith(".js")).reduce((s, r) => s + (r.transferSize || 0), 0));
  return { ...nav, ready, jsTransfer: js };
}

const median = xs => { const s = [...xs].sort((a, b) => a - b); return s.length ? s[Math.floor((s.length - 1) / 2)] : null; };
const results = { label, date: new Date().toISOString(), runs: RUNS, hard: {}, nav: {}, workflow: {}, interactions: {} };
const push = (bucket, key, value) => ((bucket[key] ??= []).push(value));

// Warm-up: compile/JIT each route once.
for (const path of routes) { await page.goto(BASE + path); await page.waitForLoadState("networkidle").catch(() => {}); }

for (let run = 0; run < RUNS; run++) {
  for (const path of routes) {
    const before = fetchCount();
    const r = await hardLoad(path);
    r.serverFetches = fetchCount() - before;
    push(results.hard, path, r);
  }
  // Client navigation from Overview via the rail / tabs.
  for (const path of routes.filter(p => p !== "/")) {
    await page.goto(BASE + "/"); await page.waitForFunction(() => document.querySelector("main h1")?.textContent === "Overview" && !document.querySelector('main [aria-busy="true"]'), null, { timeout: 60000 });
    await page.waitForTimeout(400);
    // Use a hidden link so every route is clickable the same way (Next <Link> semantics via router.push).
    await page.evaluate(path => { window.__navTarget = path; }, path);
    const sel = `nav[aria-label="Main"] a[href="${path}"], header nav a[href="${path}"], a[href="${path}"]`;
    const has = await page.$(sel);
    if (!has) continue;
    const before = fetchCount();
    const r = await timed(sel, pageReady, { path });
    r.serverFetches = fetchCount() - before;
    push(results.nav, path, r);
  }

  // Workflow: Overview -> Cash flow "Out" -> Uncategorized (and same for In).
  for (const flow of ["out", "in"]) {
    const steps = {};
    const t0 = Date.now();
    await page.goto(BASE + "/data:,").catch(() => {});
    const tl = Date.now();
    await page.goto(BASE + "/", { waitUntil: "commit" });
    await page.waitForFunction(() => document.querySelector("main h1")?.textContent === "Overview" && document.querySelector("#cash-flow") && !document.querySelector('main [aria-busy="true"]'), null, { timeout: 60000, polling: "raf" });
    steps.overview = { readyMs: Date.now() - tl };
    // Step 2: scroll to Cash flow (anchor; no request) — record as instant interaction.
    await page.locator("#cash-flow").scrollIntoViewIfNeeded();
    let before = fetchCount();
    const label = flow === "out" ? "Out" : "In";
    const flowSel = `#cash-flow [role="group"][aria-label="Show"] a:nth-child(${flow === "in" ? 2 : 3})`;
    const heading = flow === "out" ? "Top categories in" : "Income by category in";
    steps.selectFlow = await timed(flowSel, `return location.search.includes("flow=${flow}") && [...document.querySelectorAll("#cash-flow h3")].some(h => h.textContent.startsWith(arg.heading)) && document.querySelector('#cash-flow [aria-pressed="true"]')?.textContent.trim() === arg.label;`, { heading, label });
    steps.selectFlow.serverFetches = fetchCount() - before;
    // Step 3: Uncategorized
    const uncSel = `#cash-flow a[href*="category=none"]`;
    if (await page.$(uncSel)) {
      before = fetchCount();
      steps.uncategorized = await timed(uncSel, pageReady + "", { path: "/money/transactions", search: "category=none" });
      steps.uncategorized.serverFetches = fetchCount() - before;
      await page.waitForSelector("main table, main [role=table], main ul", { timeout: 30000 });
    } else steps.uncategorized = { missing: true };
    steps.totalMs = (steps.overview.readyMs) + steps.selectFlow.readyMs + (steps.uncategorized.readyMs ?? 0);
    push(results.workflow, flow, steps);
  }

  // Transactions interactions: group by Category, open a row drawer, close via Escape, filter by account select submit.
  await page.goto(BASE + "/money/transactions");
  await page.waitForFunction(() => document.querySelector("main h1")?.textContent === "Transactions" && document.querySelector("main table"), null, { timeout: 60000 });
  let before = fetchCount();
  const g = await timed(`nav[aria-label="Group by"] a:nth-of-type(2)`, `return location.search.includes("group=category") && document.querySelector('nav[aria-label="Group by"] a[aria-current="true"]')?.textContent === "Category" && document.querySelector("main table");`, {});
  g.serverFetches = fetchCount() - before; push(results.interactions, "groupByCategory", g);
  before = fetchCount();
  const d = await timed(`main table tbody a[href*="transaction="]`, `return location.search.includes("transaction=") && document.querySelector('aside[aria-label]:not([aria-label="Loading transaction"])');`, {});
  d.serverFetches = fetchCount() - before; push(results.interactions, "openDrawer", d);
  // Cash flow month bar via Show tabs back to Both
  await page.goto(BASE + "/?flow=out&show=out#cash-flow");
  await page.waitForFunction(() => document.querySelector("#cash-flow") && !document.querySelector('main [aria-busy="true"]'), null, { timeout: 60000 });
  before = fetchCount();
  const both = await timed(`#cash-flow [role="group"][aria-label="Show"] a:nth-child(1)`, `return !location.search.includes("show=") && document.querySelector('#cash-flow [aria-pressed="true"]')?.textContent.trim() === "Both";`, {});
  both.serverFetches = fetchCount() - before; push(results.interactions, "cashFlowBoth", both);
  console.error(`run ${run + 1}/${RUNS} done`);
}

// Summaries
const summary = { label, runs: RUNS, hard: {}, nav: {}, workflow: {}, interactions: {} };
for (const [k, v] of Object.entries(results.hard)) summary.hard[k] = { ttfb: median(v.map(x => x.ttfb)), fcp: median(v.map(x => x.fcp)), lcp: median(v.map(x => x.lcp)), ready: median(v.map(x => x.ready)), jsKB: Math.round(median(v.map(x => x.jsTransfer)) / 1024), serverFetches: median(v.map(x => x.serverFetches)) };
for (const [k, v] of Object.entries(results.nav)) summary.nav[k] = { first: median(v.map(x => x.firstMs)), ready: median(v.map(x => x.readyMs)), serverFetches: median(v.map(x => x.serverFetches)) };
for (const [k, v] of Object.entries(results.interactions)) summary.interactions[k] = { first: median(v.map(x => x.firstMs)), ready: median(v.map(x => x.readyMs)), serverFetches: median(v.map(x => x.serverFetches)) };
for (const [k, v] of Object.entries(results.workflow)) summary.workflow[k] = { overview: median(v.map(x => x.overview.readyMs)), selectFlowFirst: median(v.map(x => x.selectFlow.firstMs)), selectFlow: median(v.map(x => x.selectFlow.readyMs)), selectFlowFetches: median(v.map(x => x.selectFlow.serverFetches)), uncategorizedFirst: median(v.map(x => x.uncategorized.firstMs ?? 0)), uncategorized: median(v.map(x => x.uncategorized.readyMs ?? 0)), uncategorizedFetches: median(v.map(x => x.uncategorized.serverFetches ?? 0)), total: median(v.map(x => x.totalMs)) };
summary.consoleErrors = [...new Set(consoleErrors)];
fs.writeFileSync(`.qa/perf/${label}.raw.json`, JSON.stringify(results, null, 1));
fs.writeFileSync(`.qa/perf/${label}.json`, JSON.stringify(summary, null, 1));
console.log(JSON.stringify(summary, null, 1));
await browser.close();
