// Preloaded into `next start` for measurement only: logs every outbound fetch (Supabase/PostgREST) with timing.
const fs = require("node:fs");
const out = process.env.FETCH_LOG || ".qa/perf/fetch.log";
const original = globalThis.fetch;
globalThis.fetch = async function (input, init) {
  const url = typeof input === "string" ? input : input instanceof URL ? input.href : input.url;
  const start = Date.now();
  try { return await original.call(this, input, init); }
  finally {
    if (!url.startsWith("http://localhost") && !url.startsWith("http://127.")) {
      const u = new URL(url);
      fs.appendFileSync(out, JSON.stringify({ start, dur: Date.now() - start, method: (init && init.method) || (typeof input === "object" && input.method) || "GET", path: u.pathname, q: decodeURIComponent(u.search).slice(0, 200) }) + "\n");
    }
  }
};

// Measures hard loads, client navigations, interactions and the Overview -> Cash flow -> In/Out -> Uncategorized workflow.
// Usage: node .qa/perf/bench.mjs <label> [runs]
import { chromium } from "@playwright/test";
import fs from "node:fs";

const label = process.argv[2] ?? "run", RUNS = Number(process.argv[3] ?? 5);
const BASE = process.env.BASE ?? "http://localhost:3000";
const FETCH_LOG = ".qa/perf/fetch.log";
const routes = ["/", "/money/transactions", "/money/organization", "/money/investigations", "/import", "/money/accounts", "/money/recurring", "/plan", "/plan/spending", "/plan/currency", "/money/wealth", "/ai", "/ai/agents", "/ai/activity", "/ai/artifacts", "/settings", "/notifications"];

const browser = await chromium.launch();
const context = await browser.newContext({ storageState: "e2e/.auth.json", viewport: { width: 1440, height: 900 } });
const page = await context.newPage();
const consoleErrors = [];
page.on("console", msg => { if (msg.type() === "error") consoleErrors.push(`${new URL(page.url()).pathname} ${msg.text().slice(0, 200)}`); });
page.on("pageerror", err => consoleErrors.push(`${new URL(page.url()).pathname} pageerror ${err.message.slice(0, 200)}`));

const fetchCount = () => fs.existsSync(FETCH_LOG) ? fs.readFileSync(FETCH_LOG, "utf8").split("\n").filter(Boolean).length : 0;

// In-page: click `selector`, then time the first DOM change under #main-content and when `readyBody` returns true.
function timed(selector, readyBody, readyArg = {}) {
  return page.evaluate(({ selector, readyBody, readyArg }) => {
    const ready = new Function("arg", readyBody);
    const arg = { ...readyArg, oldMain: document.querySelector("main") };
    const el = document.querySelector(selector);
    if (!el) throw new Error(`missing ${selector}`);
    let first = null;
    const t0 = performance.now();
    const mo = new MutationObserver(() => { if (first === null) first = performance.now() - t0; });
    mo.observe(document.getElementById("main-content") ?? document.body, { childList: true, subtree: true, characterData: true, attributes: true });
    el.click();
    return new Promise((resolve, reject) => {
      const tick = () => {
        const now = performance.now();
        if (ready(arg)) { mo.disconnect(); resolve({ firstMs: Math.round(first ?? now - t0), readyMs: Math.round(now - t0) }); return; }
        if (now - t0 > 30000) { mo.disconnect(); reject(new Error(`timeout ${selector} ${location.href}`)); return; }
        requestAnimationFrame(tick);
      };
      tick();
    });
  }, { selector, readyBody, readyArg });
}
// Ready: on the target path, a new non-busy <main> with an h1 and nothing aria-busy inside it.
const pageReady = `const m = document.querySelector("main"); return location.pathname === arg.path && (!arg.search || location.search.includes(arg.search)) && !!m && m !== arg.oldMain && !m.matches('[aria-busy="true"]') && !!m.querySelector("h1") && !m.querySelector('[aria-busy="true"]');`;
const settled = () => !!document.querySelector("main h1") && !document.querySelector('main[aria-busy="true"], main [aria-busy="true"]') && document.readyState === "complete";

async function hardLoad(path) {
  await page.goto("about:blank");
  const t = Date.now();
  await page.goto(BASE + path, { waitUntil: "commit" });
  await page.waitForFunction(settled, null, { timeout: 60000, polling: "raf" });
  const ready = Date.now() - t;
  const nav = await page.evaluate(() => new Promise(resolve => {
    const n = performance.getEntriesByType("navigation")[0];
    let lcp = null;
    new PerformanceObserver(list => { const e = list.getEntries().at(-1); if (e) lcp = e.startTime; }).observe({ type: "largest-contentful-paint", buffered: true });
    const fcp = performance.getEntriesByName("first-contentful-paint")[0]?.startTime ?? null;
    const js = performance.getEntriesByType("resource").filter(r => r.name.includes("/_next/static/") && r.name.endsWith(".js")).reduce((s, r) => s + (r.encodedBodySize || 0), 0);
    setTimeout(() => resolve({ ttfb: Math.round(n.responseStart), fcp: fcp && Math.round(fcp), lcp: lcp && Math.round(lcp), htmlKB: Math.round(n.encodedBodySize / 1024), jsKB: Math.round(js / 1024) }), 50);
  }));
  return { ...nav, ready };
}

const median = xs => { const s = xs.filter(x => typeof x === "number").sort((a, b) => a - b); return s.length ? s[Math.floor((s.length - 1) / 2)] : null; };
const results = { label, date: new Date().toISOString(), runs: RUNS, hard: {}, nav: {}, workflow: {}, interactions: {} };
const push = (bucket, key, value) => ((bucket[key] ??= []).push(value));
const gotoSettled = async (url, extra = settled) => { await page.goto(BASE + url); await page.waitForFunction(extra, null, { timeout: 60000, polling: "raf" }); await page.waitForTimeout(300); };

// Warm-up: compile/JIT every route once.
for (const path of routes) { await page.goto(BASE + path); await page.waitForLoadState("networkidle").catch(() => {}); }

for (let run = 0; run < RUNS; run++) {
  for (const path of routes) {
    const before = fetchCount();
    const r = await hardLoad(path);
    await page.waitForTimeout(200);
    r.serverFetches = fetchCount() - before;
    push(results.hard, path, r);
  }
  // Client navigation from Overview via rail/tab links.
  for (const path of routes.filter(p => p !== "/")) {
    await gotoSettled("/");
    const sel = `#main-content ~ * a[href="${path}"], nav a[href="${path}"], header a[href="${path}"]`;
    if (!await page.$(sel)) {
      // Section tabs only render inside the section; navigate to the section first, then click the tab.
      continue;
    }
    const before = fetchCount();
    const r = await timed(sel, pageReady, { path });
    r.serverFetches = fetchCount() - before;
    push(results.nav, path, r);
  }
  // Tabs within sections (Activity → Organization/Import, Plan → Spending/Currency, Agents → Activity log).
  for (const [from, to] of [["/money/transactions", "/money/organization"], ["/money/organization", "/import"], ["/plan", "/plan/spending"], ["/plan/spending", "/plan/currency"], ["/ai/agents", "/ai/activity"]]) {
    await gotoSettled(from);
    const before = fetchCount();
    const r = await timed(`header nav a[href="${to}"]`, pageReady, { path: to });
    r.serverFetches = fetchCount() - before;
    push(results.nav, `${from} -> ${to}`, r);
  }

  // Workflow: Overview -> Cash flow -> In/Out -> Uncategorized.
  for (const flow of ["out", "in"]) {
    const steps = {};
    await page.goto("about:blank");
    const tl = Date.now();
    let before = fetchCount();
    await page.goto(BASE + "/", { waitUntil: "commit" });
    await page.waitForFunction(() => document.querySelector("main h1")?.textContent === "Overview" && !!document.querySelector("#cash-flow canvas") && !document.querySelector('main [aria-busy="true"]'), null, { timeout: 60000, polling: "raf" });
    steps.overview = { readyMs: Date.now() - tl, serverFetches: fetchCount() - before };
    await page.locator("#cash-flow").scrollIntoViewIfNeeded();
    await page.waitForTimeout(300);
    before = fetchCount();
    const name = flow === "out" ? "Out" : "In";
    const heading = flow === "out" ? "Top categories in" : "Income by category in";
    steps.selectFlow = await timed(`#cash-flow [role="group"][aria-label="Show"] a:nth-child(${flow === "in" ? 2 : 3})`,
      `return location.search.includes("flow=${flow}") && [...document.querySelectorAll("#cash-flow h3")].some(h => h.textContent.startsWith(arg.heading)) && document.querySelector('#cash-flow [aria-pressed="true"]')?.textContent.trim() === arg.name;`, { heading, name });
    await page.waitForTimeout(300);
    steps.selectFlow.serverFetches = fetchCount() - before;
    const unc = `#cash-flow a[href*="category=none"]`;
    if (await page.$(unc)) {
      before = fetchCount();
      steps.uncategorized = await timed(unc, `${pageReady.replace(/return /, "if (!document.querySelector('main table')) return false; return ")}`, { path: "/money/transactions", search: "category=none" });
      await page.waitForTimeout(300);
      steps.uncategorized.serverFetches = fetchCount() - before;
    } else steps.uncategorized = { missing: true };
    steps.totalMs = steps.overview.readyMs + steps.selectFlow.readyMs + (steps.uncategorized.readyMs ?? 0);
    push(results.workflow, flow, steps);
  }

  // Transactions interactions.
  await gotoSettled("/money/transactions", () => document.querySelector("main h1")?.textContent === "Transactions" && !!document.querySelector("main table"));
  let before = fetchCount();
  const group = await timed(`nav[aria-label="Group by"] a:nth-of-type(2)`, `return location.search.includes("group=category") && document.querySelector('nav[aria-label="Group by"] a[aria-current="true"]')?.textContent === "Category" && !!document.querySelector("main table");`);
  await page.waitForTimeout(300); group.serverFetches = fetchCount() - before; push(results.interactions, "transactions: group by category", group);
  before = fetchCount();
  const drawer = await timed(`main table tbody a[href*="transaction="]`, `return location.search.includes("transaction=") && !!document.querySelector('aside[aria-label]:not([aria-label="Loading transaction"])');`);
  await page.waitForTimeout(300); drawer.serverFetches = fetchCount() - before; push(results.interactions, "transactions: open drawer", drawer);
  // Filter: submit the filter form with the first account selected.
  await gotoSettled("/money/transactions", () => document.querySelector("main h1")?.textContent === "Transactions" && !!document.querySelector("main table"));
  const account = await page.$eval(`form[aria-label="Filter transactions"] select[name="account"]`, s => s.options[1]?.value).catch(() => null);
  if (account) {
    await page.selectOption(`form[aria-label="Filter transactions"] select[name="account"]`, account);
    before = fetchCount();
    const filter = await timed(`form[aria-label="Filter transactions"] button[type="submit"], form[aria-label="Filter transactions"] button:not([type="button"])`, `return location.search.includes("account=") && !!document.querySelector('ul[aria-label="Active filters"] li a') && !!document.querySelector("main table");`);
    await page.waitForTimeout(300); filter.serverFetches = fetchCount() - before; push(results.interactions, "transactions: filter by account", filter);
  }
  // Overview: Show "Both" after a flow is open.
  await gotoSettled("/?flow=out&show=out#cash-flow", () => !!document.querySelector("#cash-flow") && !document.querySelector('main [aria-busy="true"]'));
  before = fetchCount();
  const both = await timed(`#cash-flow [role="group"][aria-label="Show"] a:nth-child(1)`, `return !location.search.includes("show=") && document.querySelector('#cash-flow [aria-pressed="true"]')?.textContent.trim() === "Both";`);
  await page.waitForTimeout(300); both.serverFetches = fetchCount() - before; push(results.interactions, "overview: cash flow Both", both);
  // Overview: month cash flow "In" row (scroll=false link into the six-month panel).
  await gotoSettled("/");
  before = fetchCount();
  const inRow = await timed(`section[aria-label="Cash flow this month"] a[href*="flow=in"]`, `return location.search.includes("flow=in") && [...document.querySelectorAll("#cash-flow h3")].some(h => h.textContent.startsWith("Income by category"));`);
  await page.waitForTimeout(300); inRow.serverFetches = fetchCount() - before; push(results.interactions, "overview: this-month In row", inRow);
  console.error(`run ${run + 1}/${RUNS} done`);
}

const summary = { label, date: results.date, runs: RUNS, hard: {}, nav: {}, workflow: {}, interactions: {} };
for (const [k, v] of Object.entries(results.hard)) summary.hard[k] = Object.fromEntries(["ttfb", "fcp", "lcp", "ready", "htmlKB", "jsKB", "serverFetches"].map(f => [f, median(v.map(x => x[f]))]));
for (const bucket of ["nav", "interactions"]) for (const [k, v] of Object.entries(results[bucket])) summary[bucket][k] = { first: median(v.map(x => x.firstMs)), ready: median(v.map(x => x.readyMs)), serverFetches: median(v.map(x => x.serverFetches)) };
for (const [k, v] of Object.entries(results.workflow)) summary.workflow[k] = {
  overview: median(v.map(x => x.overview.readyMs)), overviewFetches: median(v.map(x => x.overview.serverFetches)),
  selectFlowFirst: median(v.map(x => x.selectFlow.firstMs)), selectFlow: median(v.map(x => x.selectFlow.readyMs)), selectFlowFetches: median(v.map(x => x.selectFlow.serverFetches)),
