export type WealthItem = WealthValue & { kind: "holding" | "asset" | "debt"; quantity_text: string | null; unit_price_text: string | null; cost_basis_minor: string | null;
  payment_account_id: string | null; annual_rate_text: string | null; monthly_payment_minor: string | null; next_payment_on: string | null;
  payment_assumption_id: string | null; payment_transaction_id: string | null; version: number; removed_at: string | null; sourceCoverage?: SourceCoverage };

export async function loadWealthItems(client: SupabaseClient, workspaceId: string, includeRemoved = false): Promise<WealthItem[]> {
  const rows: WealthItem[] = [];
  for (let offset = 0; ; offset += 500) {
    let query = client.from("wealth_items").select("id, name, kind, currency_code, amount_minor::text, quantity_text, unit_price_text, cost_basis_minor::text, as_of, linked_account_id, payment_account_id, annual_rate_text, monthly_payment_minor::text, next_payment_on, payment_assumption_id, payment_transaction_id, version, removed_at")
      .eq("workspace_id", workspaceId).order("created_at").order("id");
    if (!includeRemoved) query = query.is("removed_at", null);
    const result = await query.range(offset, offset + 499);
    if (result.error) throw result.error;
    rows.push(...result.data as WealthItem[]);
    if (!result.data || result.data.length < 500) return rows.map(row => ({ ...row,
      sourceCoverage: buildSourceCoverage({ from: row.as_of, to: row.as_of, currencyCode: row.currency_code, recordBasis: "manual_wealth" }, []) }));
  }
}

export function buildDebtForecast(items: WealthItem[], accounts: { id: string; type?: string; currency_code: string; archived_at?: string | null }[], ledger: { id: string; account_id: string; amount_minor: string | number; currency_code: string; posted_on: string; status: string; pending_released_minor?: string }[], assumptions: { id: string; account_id: string | null; amount_minor: string; currency_code: string; cadence: string; starts_on: string; ends_on: string | null }[], today: string, days: number): { events: { date: string; accountId: string; currencyCode: string; amountMinor: bigint }[]; excludedAssumptionIds: string[]; missingInputs: string[] } {
  const minor = (value: string | number) => { if (typeof value === "number" && !Number.isSafeInteger(value)) throw new Error("Unsafe debt ledger money"); return BigInt(value); };
  const events: { date: string; accountId: string; currencyCode: string; amountMinor: bigint }[] = [];
  const excludedAssumptionIds: string[] = []; const missingInputs: string[] = []; const provenance = new Set<string>();
  for (const item of items.filter(item => item.kind === "debt" && !item.removed_at)) {
    const missing = (reason: string) => missingInputs.push(`debt:${item.id}:${reason}`);
    if (BigInt(item.amount_minor) === 0n) continue;
    if (item.as_of !== today) { missing("principal valuation is historical"); continue; }
    const account = accounts.find(account => account.id === item.payment_account_id);
    if (!account || account.archived_at || !["checking", "savings", "cash", "wallet"].includes(account.type ?? "") || account.currency_code !== item.currency_code) { missing("liquid repayment account"); continue; }

type WealthEvent = { id: string; item_id: string; before: WealthItem | null; after: WealthItem; created_at: string; undone_at: string | null };

/** Every saved valuation event (newest first), paged; the Wealth page lists them and both it and Home chart them. */
export async function loadWealthEvents(db: SupabaseClient, workspaceId: string): Promise<WealthEvent[]> {
  const rows: WealthEvent[] = [];
  for (let offset = 0; ; offset += 1000) {
    const { data, error } = await db.from("wealth_events").select("id, item_id, before, after, created_at, undone_at").eq("workspace_id", workspaceId)
      .order("created_at", { ascending: false }).order("id").range(offset, offset + 999);
    if (error) throw error;
    rows.push(...(data ?? []) as WealthEvent[]);
    if (!data || data.length < 1000) return rows;
  }
}

// Valuation history = every non-undone saved version of each item, plus the current row.
export function valuationHistory(events: WealthEvent[], items: WealthItem[]): Valuation[] {
  return [...events.filter(event => !event.undone_at && !event.after.removed_at).map(event => ({ ...event.after, item_id: event.item_id, created_at: event.created_at, amount_minor: String(event.after.amount_minor) })),
    ...items.map(item => ({ ...item, item_id: item.id, created_at: "9999-12-31" }))];
}

export async function loadSourceCoverage(db: SupabaseClient, workspaceId: string, scope: CoverageScope,
  rows: EffectiveRow[], canReadImports: boolean): Promise<SourceCoverage> {
  const metadata = await loadSourceCoverageMetadata(db, workspaceId, canReadImports);
  return buildSourceCoverage(scope, rows, metadata?.imports, metadata?.sources);
}

// Internal shared read for readers with several periods/currencies. Consumers
// receive the envelope, never these individual observations or import identities.
// Memoized per request: Home, its cashflow and its insights all read the same metadata.
export const loadSourceCoverageMetadata = cache(async (db: SupabaseClient, workspaceId: string, canReadImports: boolean) => {
  if (!canReadImports) return undefined;
  async function all<T>(table: string, columns: string): Promise<T[]> {
    const page = async (offset: number, count?: "exact") => {
      const result = await db.from(table).select(columns, count ? { count } : undefined).eq("workspace_id", workspaceId).order("id").range(offset, offset + 499);
      if (result.error) throw result.error;
      return { rows: (result.data ?? []) as T[], count: result.count };
    };
    // The first page's count lets the remaining pages load in parallel; the loop still
