export default async function AgentRunsPage({ searchParams }: { searchParams: Promise<{ import?: string }> }) {
  let context: Awaited<ReturnType<typeof requireWorkspace>>;
  try { context = await requireWorkspace(); } catch { redirect("/login"); }
  const { supabase, workspace } = context;
  const importId = z.uuid().safeParse((await searchParams).import);
  if (importId.success) {
    const run = await supabase.from("agent_runs").select("id").eq("workspace_id", workspace.id).eq("import_id", importId.data).maybeSingle();
    if (run.data) redirect(`/ai/agents/${run.data.id}`);
  }
  const runs = await supabase.from("agent_runs").select("id, status, trigger, created_at, briefing").eq("workspace_id", workspace.id).order("created_at", { ascending: false }).limit(20);
  const counts = await supabase.from("agent_proposals").select("run_id, status").eq("workspace_id", workspace.id).eq("status", "proposed").not("run_id", "is", null).limit(1000);
  const open = new Map<string, number>();
  for (const row of counts.data ?? []) open.set(row.run_id, (open.get(row.run_id) ?? 0) + 1);
  return <main className="mx-auto w-full max-w-[1400px] space-y-6 px-4 py-6 sm:px-8 lg:py-8">
    <header className="flex flex-wrap items-end gap-4">
      <div className="mr-auto flex flex-col gap-1"><p className="eyebrow">Runs after every import · {runs.data?.length ?? 0} recent {runs.data?.length === 1 ? "run" : "runs"}</p><h1 className="page-title">Agent team</h1>
  ["home", "Customize Home"], ["banks", "Connected banks"], ["summaries", "Scheduled summaries"], ["usage", "AI usage"], ["danger", "Danger zone"],
] as const;

async function loadDashboard({ supabase, workspace }: Workspace) {
  const layout = await supabase.from("dashboard_layouts").select("items, version").eq("workspace_id", workspace.id).maybeSingle();
  if (layout.error) throw layout.error;
  const parsedLayout = layout.data ? dashboardLayoutSchema.safeParse(layout.data.items) : null;
  const saved = dashboardItems(parsedLayout?.success ? parsedLayout.data : null);
  // Pinned artifacts are listed by title; deleted ones are left out, so saving drops them.
  const ids = saved.map(artifactIdFromKey).filter(id => id !== null);
  const pinned = ids.length ? await supabase.from("artifacts").select("id, title").eq("workspace_id", workspace.id).in("id", ids).is("deleted_at", null) : { data: [], error: null };
  if (pinned.error) throw pinned.error;
  const labels: Record<string, string> = { ...BUILTIN_WIDGETS, ...Object.fromEntries(pinned.data.map(artifact => [`artifact:${artifact.id}`, `Artifact: ${artifact.title}`])) };
  const ordered = saved.filter(key => Object.hasOwn(labels, key));
  return { version: layout.data?.version ?? 0, ordered, labels, choices: [...new Set([...ordered, ...Object.keys(BUILTIN_WIDGETS)])] };
}

async function loadRuns({ supabase, workspace }: Workspace): Promise<SummaryRun[] | null> {
  const scheduled = await supabase.from("summary_runs").select("id,job_id,cadence,period_start").eq("workspace_id", workspace.id).order("created_at", { ascending: false }).limit(5);
  if (scheduled.error) return null;
  const jobs = scheduled.data.length ? await supabase.from("background_jobs").select("id,status,stage,error").eq("workspace_id", workspace.id).in("id", scheduled.data.map(run => run.job_id)) : null;
  if (jobs?.error) return null;
  return scheduled.data.map(run => {
    const job = jobs?.data?.find(job => job.id === run.job_id);
    return { ...run, status: job?.status ?? "unknown", stage: job?.stage ?? "unavailable", error: job?.error ?? null };
  });
}

