/** Net worth over time; hovering (or tapping) shows the exact amount and date at that point. */
export function NetWorthChart({ points, label }: { points: NetWorthPoint[]; label: string }) {
  const [active, setActive] = useState<number | null>(null);
  const gradient = useId();
  const values = points.map(point => point.y);
  const min = Math.min(...values), max = Math.max(...values), span = max - min || 1;
  const x = (index: number) => points.length === 1 ? WIDTH / 2 : (index / (points.length - 1)) * WIDTH;
  const y = (value: number) => HEIGHT - PAD - ((value - min) / span) * (HEIGHT - PAD * 2);
  const line = points.map((point, index) => `${x(index).toFixed(1)},${y(point.y).toFixed(1)}`).join(" ");
  const pick = (clientX: number, rect: DOMRect) => setActive(Math.max(0, Math.min(points.length - 1, Math.round(((clientX - rect.left) / rect.width) * (points.length - 1)))));
  const shown = active === null ? null : points[active];
  return <div className="relative" onPointerLeave={() => setActive(null)}>
    <svg role="img" aria-label={label} viewBox={`0 0 ${WIDTH} ${HEIGHT}`} preserveAspectRatio="none" className="h-[140px] w-full cursor-crosshair touch-none overflow-visible text-brand"
      onPointerMove={event => pick(event.clientX, event.currentTarget.getBoundingClientRect())} onPointerDown={event => pick(event.clientX, event.currentTarget.getBoundingClientRect())}>
      <defs><linearGradient id={gradient} x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stopColor="currentColor" stopOpacity={0.22} /><stop offset="100%" stopColor="currentColor" stopOpacity={0} /></linearGradient></defs>
      <polygon points={`0,${HEIGHT} ${line} ${WIDTH},${HEIGHT}`} fill={`url(#${gradient})`} />
      <polyline points={line} fill="none" stroke="currentColor" strokeWidth={1.75} strokeLinejoin="round" strokeLinecap="round" vectorEffect="non-scaling-stroke" />
      {active !== null && <line x1={x(active)} x2={x(active)} y1={0} y2={HEIGHT} stroke="var(--color-muted-foreground)" strokeOpacity={0.5} strokeDasharray="3 3" vectorEffect="non-scaling-stroke" />}
    </svg>
    {shown && <>
      <span aria-hidden="true" className="pointer-events-none absolute size-2.5 -translate-x-1/2 -translate-y-1/2 rounded-full border-2 border-card bg-brand shadow"
        style={{ left: `${(x(active!) / WIDTH) * 100}%`, top: `${(y(shown.y) / HEIGHT) * 100}%` }} />
      <div role="status" className="pointer-events-none absolute z-10 rounded-lg border border-border bg-card px-3 py-2 shadow-lg"
        style={{ left: `clamp(0px, calc(${(x(active!) / WIDTH) * 100}% - 4.5rem), calc(100% - 9rem))`, top: `max(0px, calc(${(y(shown.y) / HEIGHT) * 100}% - 4.75rem))` }}>
        <p className="whitespace-nowrap font-mono text-sm font-semibold">{shown.amount}</p>
        <p className="whitespace-nowrap text-[11px] text-muted-foreground">{shown.label}</p>
      </div>
    </>}
  </div>;
}
"use client";

import { ReactECharts, useThemeColors } from "@/components/chart";
import type { ModelUsage } from "@/lib/ai/usage";

// One horizontal bar per model, split into input and output tokens. Models are ordered largest first.
export function UsageChart({ models, locale }: { models: ModelUsage[]; locale: string }) {
  const colors = useThemeColors();
  const format = (value: number) => new Intl.NumberFormat(locale).format(value);
  const axis = { axisLine: { lineStyle: { color: colors.border } }, axisLabel: { color: colors.muted }, splitLine: { lineStyle: { color: colors.border, type: "dashed" } } };
  const segment = { barMaxWidth: 28, itemStyle: { borderColor: colors.card, borderWidth: 2 } };
  const summary = models.map(model => `${model.model_id}: ${format(model.input_tokens + model.output_tokens)} tokens`).join("; ");
  return (
    <div>
      <div role="img" aria-label={`Tokens per model. ${summary}`}>
        <ReactECharts
          style={{ height: Math.max(160, models.length * 56 + 64) }}
          option={{
            grid: { left: 8, right: 16, top: 40, bottom: 8, containLabel: true },
            legend: { top: 0, textStyle: { color: colors.muted } },
            tooltip: { trigger: "axis", axisPointer: { type: "shadow" }, valueFormatter: format },
            xAxis: { type: "value", ...axis, axisLabel: { color: colors.muted, formatter: format } },
            yAxis: { type: "category", inverse: true, data: models.map(model => model.model_id), ...axis },
            series: [
              { ...segment, name: "Input", type: "bar", stack: "tokens", data: models.map(model => model.input_tokens), color: colors.input },
              { ...segment, name: "Output", type: "bar", stack: "tokens", data: models.map(model => model.output_tokens), color: colors.output, itemStyle: { ...segment.itemStyle, borderRadius: [0, 4, 4, 0] } },
            ],
          }}
        />
      </div>
      <details className="mt-3 text-sm text-muted-foreground">
        <summary className="cursor-pointer">View as table</summary>
        <table className="mt-2 w-full text-left tabular-nums">
          <thead><tr className="border-b border-border"><th className="py-1.5 font-medium">Model</th><th className="py-1.5 text-right font-medium">Requests</th><th className="py-1.5 text-right font-medium">Input</th><th className="py-1.5 text-right font-medium">Output</th><th className="py-1.5 text-right font-medium">Total</th></tr></thead>
          <tbody>{models.map(model => <tr key={model.model_id} className="border-b border-border last:border-0">
            <th scope="row" className="py-1.5 font-normal break-all text-foreground">{model.model_id}</th>
            <td className="py-1.5 text-right">{format(model.requests)}</td>
            <td className="py-1.5 text-right">{format(model.input_tokens)}</td>
            <td className="py-1.5 text-right">{format(model.output_tokens)}</td>
            <td className="py-1.5 text-right">{format(model.input_tokens + model.output_tokens)}</td>
          </tr>)}</tbody>
        </table>
      </details>
