// Time from navigation to the Overview cash-flow chart canvas, plus echarts JS bytes; optional CDP network throttling.
// Usage: node .qa/perf/chart.mjs <label> [runs]
import { chromium } from "@playwright/test";
import fs from "node:fs";
const label = process.argv[2] ?? "chart", RUNS = Number(process.argv[3] ?? 7), BASE = process.env.BASE ?? "http://localhost:3217";
const browser = await chromium.launch();
const out = {};
for (const profile of ["none", "4g"]) {
  const context = await browser.newContext({ storageState: "e2e/.auth.json", viewport: { width: 1440, height: 900 } });
  const page = await context.newPage();
  const cdp = await context.newCDPSession(page);
  await cdp.send("Network.enable");
  await cdp.send("Network.setCacheDisabled", { cacheDisabled: true });
  if (profile === "4g") await cdp.send("Network.emulateNetworkConditions", { offline: false, latency: 60, downloadThroughput: 9_000_000 / 8, uploadThroughput: 1_500_000 / 8 });
  await page.goto(BASE + "/"); await page.waitForSelector("#cash-flow canvas", { timeout: 60000 });
  const rows = [];
  for (let i = 0; i < RUNS; i++) {
    await page.goto("about:blank");
    const t = Date.now();
    await page.goto(BASE + "/", { waitUntil: "commit" });
    await page.waitForSelector("#cash-flow canvas", { timeout: 60000 });
    const chart = Date.now() - t;
    const js = await page.evaluate(() => performance.getEntriesByType("resource").filter(e => e.name.includes("/_next/static/") && e.name.endsWith(".js")).reduce((s, e) => s + e.encodedBodySize, 0));
    rows.push({ chart, jsKB: Math.round(js / 1024) });
  }
  const sorted = rows.map(r => r.chart).sort((a, b) => a - b);
  out[profile] = { min: sorted[0], median: sorted[Math.floor((sorted.length - 1) / 2)], max: sorted.at(-1), jsKB: rows.at(-1).jsKB, runs: rows.map(r => r.chart) };
  await context.close();
}
fs.writeFileSync(`.qa/perf/${label}.json`, JSON.stringify(out, null, 1));
console.log(JSON.stringify(out));
await browser.close();

